class Solution {
    public double findMaxAverage(int[] nums,int k){
        long window=0;
        for(int i=0;i<k;i++)window+=nums[i];
        long best=window;
        for(int right=k;right<nums.length;right++){
            window+=nums[right]-nums[right-k];
            best=Math.max(best,window);
        }
        return(double)best/k;
    }
}

code.kotlin:
class Solution {
    fun findMaxAverage(nums:IntArray,k:Int):Double{
        var window=0L;
        for(i in 0 until k)window+=nums[i];
        var best=window;
        for(right in k until nums.size){
            window+=nums[right]-nums[right-k];
            best=maxOf(best,window)
        };
        return best.toDouble()/k
    }
}

code.cpp:
class Solution {
    public: double findMaxAverage(vector<int>& nums,int k){
        long long window=accumulate(nums.begin(),nums.begin()+k,0LL),best=window;
        for(int right=k;right<(int)nums.size();++right){
            window+=nums[right]-nums[right-k];
            best=max(best,window);
        }
        return(double)best/k;
    }
};
